@Override public final synchronized BigtableSource splitAtFraction(double fraction){
  ByteKey splitKey;
  try {
    splitKey = rangeTracker.getRange().interpolateKey(fraction);
  } catch (IllegalArgumentException | IndexOutOfBoundsException | NullPointerException e) {
    LOG.info("%s: Failed to interpolate key for fraction %s. Exception: %s", rangeTracker.getRange(), fraction, e.getMessage());
    return null;
  }
  LOG.debug("Proposing to split {} at fraction {} (key {})", rangeTracker, fraction, splitKey);
  BigtableSource primary = source.withEndKey(splitKey);
  BigtableSource residual = source.withStartKey(splitKey);
  if (!rangeTracker.trySplitAtPosition(splitKey)) {
    return null;
  }
  this.source = primary;
  return residual;
}
